async function init(db){
 await db.exec(`CREATE TABLE IF NOT EXISTS modalities(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,min_players INTEGER NOT NULL,max_players INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1);
 CREATE TABLE IF NOT EXISTS teams(id INTEGER PRIMARY KEY AUTOINCREMENT,class_name TEXT NOT NULL,modality_id INTEGER NOT NULL,team_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(modality_id) REFERENCES modalities(id));
 CREATE TABLE IF NOT EXISTS players(id INTEGER PRIMARY KEY AUTOINCREMENT,team_id INTEGER NOT NULL,name TEXT NOT NULL,gender TEXT,FOREIGN KEY(team_id) REFERENCES teams(id) ON DELETE CASCADE); CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL); INSERT OR IGNORE INTO settings(key,value) VALUES('registrations_open','1'); INSERT OR IGNORE INTO settings(key,value) VALUES('registration_start','2026-11-16T00:00'); INSERT OR IGNORE INTO settings(key,value) VALUES('current_interclass_date','2026-10-03'); CREATE TABLE IF NOT EXISTS draws(id INTEGER PRIMARY KEY AUTOINCREMENT,modality_id INTEGER NOT NULL,round_no INTEGER NOT NULL,match_no INTEGER NOT NULL,team1_id INTEGER,team2_id INTEGER,winner_id INTEGER,score1 INTEGER,score2 INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS interclass_editions(id INTEGER PRIMARY KEY AUTOINCREMENT,event_date TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS group_draws(id INTEGER PRIMARY KEY AUTOINCREMENT,modality_id INTEGER NOT NULL,group_name TEXT NOT NULL,team_id INTEGER NOT NULL,position_no INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS hall_of_fame(id INTEGER PRIMARY KEY AUTOINCREMENT,event_date TEXT NOT NULL,modality_id INTEGER NOT NULL,modality_name TEXT NOT NULL,class_name TEXT NOT NULL,team_name TEXT,placement INTEGER NOT NULL DEFAULT 1,champion_names TEXT NOT NULL,photo TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS editable_content(content_key TEXT PRIMARY KEY,html TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);`); try{await db.exec(`ALTER TABLE teams ADD COLUMN gender TEXT;`)}catch{} try{await db.exec(`ALTER TABLE draws ADD COLUMN winner_id INTEGER;`)}catch{} try{await db.exec(`ALTER TABLE draws ADD COLUMN score1 INTEGER;`)}catch{} try{await db.exec(`ALTER TABLE draws ADD COLUMN score2 INTEGER;`)}catch{} try{await db.exec(`ALTER TABLE modalities ADD COLUMN custom INTEGER NOT NULL DEFAULT 0;`)}catch{} try{await db.exec(`ALTER TABLE modalities ADD COLUMN individual INTEGER NOT NULL DEFAULT 0;`)}catch{} try{await db.exec(`ALTER TABLE modalities ADD COLUMN gender_mode TEXT NOT NULL DEFAULT 'mixed';`)}catch{} try{await db.exec(`ALTER TABLE modalities ADD COLUMN emoji TEXT NOT NULL DEFAULT '🏆';`)}catch{} try{await db.exec(`ALTER TABLE modalities ADD COLUMN mixed_min_m INTEGER NOT NULL DEFAULT 0;`)}catch{} try{await db.exec(`ALTER TABLE modalities ADD COLUMN mixed_min_f INTEGER NOT NULL DEFAULT 0;`)}catch{} try{await db.exec(`ALTER TABLE players ADD COLUMN gender TEXT;`)}catch{} try{await db.exec(`ALTER TABLE teams ADD COLUMN is_test INTEGER NOT NULL DEFAULT 0;`)}catch{} try{await db.exec(`UPDATE modalities SET emoji=CASE name WHEN 'Badminton' THEN '🏸' WHEN 'Basquete 3x3' THEN '🏀' WHEN 'Basquete (Feminino)' THEN '🏀' WHEN 'Futsal' THEN '⚽' WHEN 'Futsal (Feminino)' THEN '⚽' WHEN 'Handebol' THEN '🤾' WHEN 'Handebol (Feminino)' THEN '🤾‍♀️' WHEN 'Pebolim' THEN '⚽' WHEN 'Queimada' THEN '🔴' WHEN 'Tênis de mesa' THEN '🏓' WHEN 'Vôlei' THEN '🏐' ELSE emoji END;`)}catch{} try{await db.exec(`UPDATE modalities SET individual=1,gender_mode='select' WHERE name IN ('Badminton','Tênis de mesa');`)}catch{}
 const c=await db.prepare("SELECT COUNT(*) n FROM modalities").first();
 if(!c?.n){
  const seed=[["Pebolim",2,2],["Ping Pong",1,1],["Basquete 3x3",3,5],["Futsal",5,10],["Vôlei",6,12],["Handebol",5,10]];
  for(const m of seed) await db.prepare("INSERT INTO modalities(name,min_players,max_players) VALUES(?,?,?)").bind(...m).run();
 }
 await db.prepare("UPDATE modalities SET name='Tênis de mesa' WHERE name='Ping Pong'").run();
 await db.prepare("UPDATE modalities SET min_players=5,max_players=10 WHERE name='Handebol'").run();
 await db.prepare("INSERT OR IGNORE INTO modalities(name,min_players,max_players) VALUES('Tênis de mesa',1,1)").run();
 await db.prepare("INSERT OR IGNORE INTO modalities(name,min_players,max_players) VALUES('Queimada',5,99)").run();
 await db.prepare("INSERT OR IGNORE INTO modalities(name,min_players,max_players) VALUES('Futsal (Feminino)',5,10)").run();
 await db.prepare("INSERT OR IGNORE INTO modalities(name,min_players,max_players) VALUES('Handebol (Feminino)',5,10)").run();
 await db.prepare("INSERT OR IGNORE INTO modalities(name,min_players,max_players) VALUES('Basquete (Feminino)',5,10)").run();
 await db.prepare("INSERT OR IGNORE INTO modalities(name,min_players,max_players) VALUES('Badminton',1,1)").run();
 if(false){
 }
}
